void isim64_cblas_caxpy(long N, const __LAPACK_float_complex * alpha, const __LAPACK_float_complex * X, long incX, __LAPACK_float_complex * Y, long incY) {
    if (!fits(N)) { too_big("cblas_caxpy", 1); return; }
    if (!fits(incX)) { too_big("cblas_caxpy", 4); return; }
    if (!fits(incY)) { too_big("cblas_caxpy", 6); return; }
    cblas_caxpy((int)N, (void *)alpha, (void *)X, (int)incX, (void *)Y, (int)incY);
}
